SELECT p.id, p.symbol, p.take_profit, p.stop_loss, (SELECT MIN(c.open_time) FROM candle c WHERE c.symbol = p.symbol AND c.interval_code = '1m' AND c.open_time >= p.closed_at AND c.open_time < p.closed_at + INTERVAL 240 MINUTE AND c.high_price >= p.take_profit) AS first_tp_candle, (SELECT MIN(c.open_time) FROM candle c WHERE c.symbol = p.symbol AND c.interval_code = '1m' AND c.open_time >= p.closed_at AND c.open_time < p.closed_at + INTERVAL 240 MINUTE AND c.low_price <= p.stop_loss) AS first_sl_candle FROM paper_position p WHERE p.id IN (158, 162, 172, 182) ORDER BY p.id;
SELECT open_time, high_price, low_price, close_price FROM candle WHERE symbol = 'ACEUSDT' AND interval_code = '1m' AND open_time BETWEEN '2026-10-12 10:05:00' AND '2026-10-12 11:06:00' AND high_price >= 0.1886 ORDER BY open_time LIMIT 20